const showroom={query:'',usage:'',favourites:false,sort:'name',context:'',shelf:'',viewer:null,timer:null,fullscreen:false};
const showroomKey=()=>source+':'+current().id;
const showroomSequence=()=>{if(!showroom.viewer?.ids)return local()&&current()._view?.showroomChoices||showroomCars();const byId=new Map(showroomAllChoices().map(c=>[c.id,c]));return showroom.viewer.ids.map(id=>byId.get(id)).filter(Boolean);};
const showroomCar=id=>current().cars.find(c=>c.id===id);
const showroomCars=()=>{if(local()&&current()._view?.galleryIds)return current()._view.galleryIds.map(showroomCar).filter(Boolean);const list=ShowroomModel.cars(current(),{...showroom,favourites:local()&&showroom.favourites}),shelf=local()&&db.planning.shelves.find(s=>s.id===showroom.shelf);return shelf?shelf.carIds.map(id=>list.find(c=>c.id===id)).filter(Boolean):list;};
function showroomPhoto(c,large=false){const p=ShowroomModel.photos(c)[0];return p?`<img src="${esc(large?p.data:thumbnailSource(p.data))}" data-focus-car="${esc(c.id)}" data-focus-photo="${esc(photoKey(c,p))}" alt="${esc(c.name)}" ${large?'':'loading="lazy"'} decoding="async">`:`<div class="showroom-placeholder">${icon('car')}<span>No photograph yet</span></div>`;}
function showroomStar(c){return local()?`<button class="showroom-star ${c.favourite?'is-favourite':''}" data-action="showroom-favourite" data-id="${esc(c.id)}" aria-label="${c.favourite?'Remove':'Add'} ${esc(c.name)} ${c.favourite?'from':'to'} favourites" aria-pressed="${!!c.favourite}">${c.favourite?'★':'☆'}</button>`:'';}
function showroomFeatured(){const c=showroomCoverCar();if(!c)return `<div class="panel"><p>No cars match your cover options.</p>${btn('Choose cover','showroom-cover-options')}</div>`;if(showroom.preferences.cover.mode!=='fixed')showroom.session.coverId=c.id;if(showroom.preferences.lastShown!==c.id){showroom.preferences.lastShown=c.id;showroomSavePreferences();}return `<section class="showroom-hero showroom-story-hero"><div class="showroom-hero-copy"><div class="label">In the spotlight</div><h2>${esc(c.name)}</h2><p class="muted">${esc([c.maker,c.scale].filter(Boolean).join(' · '))}</p><div class="row">${(c.usage||[]).slice(0,3).map(u=>badge(u,'usage')).join('')}</div>${showroomStory(c)}<div class="actions mt">${btn('View photos','showroom-open','primary',c.id)}${btn('View car →','showroom-car','',c.id)}${showroom.preferences.cover.mode==='rotate'?btn(showroom.coverPaused?'Resume cover':'Pause cover','showroom-cover-pause'):''}</div></div><button class="showroom-hero-photo" data-action="showroom-open" data-id="${esc(c.id)}" aria-label="View photographs of ${esc(c.name)}">${showroomPhoto(c,true)}</button></section>`;}
function showroomGallery(){const list=showroomCars();if(!list.length)return empty((current()._view?.activeCars??current().cars.filter(c=>!c.archived).length)>0?'No cars match your selection':'Your showroom is ready',(current()._view?.activeCars??current().cars.filter(c=>!c.archived).length)>0?'Try another search or clear the filters.':'Cars added to your collection will appear here. Add photographs on each car’s Photos & documents page.',btn((current()._view?.activeCars??current().cars.filter(c=>!c.archived).length)>0?'Clear filters':'Browse cars',(current()._view?.activeCars??current().cars.filter(c=>!c.archived).length)>0?'showroom-clear':'nav','',(current()._view?.activeCars??current().cars.filter(c=>!c.archived).length)>0?'':'Cars'));return `<div class="showroom-grid">${list.map(c=>`<article class="showroom-card"><button class="showroom-card-open" data-action="showroom-open" data-id="${esc(c.id)}" aria-label="View photographs of ${esc(c.name)}"><div class="showroom-card-photo">${showroomPhoto(c)}</div><div class="showroom-card-caption"><h3>${esc(c.name)}</h3><p>${esc([c.maker,c.scale].filter(Boolean).join(' · '))}</p><div class="row">${(c.usage||[]).slice(0,2).map(u=>badge(u,'usage')).join('')}</div></div></button>${showroomStar(c)}</article>`).join('')}</div>`;}
function renderShowroom(){const usages=current()._view?.usage||[...new Set(current().cars.filter(c=>!c.archived).flatMap(c=>c.usage||[]))].sort();return `<div class="showroom-page">${heading('Showroom','Your collection, on display.',btn('Cover options','showroom-cover-options')+btn('Presentation','showroom-presentation')+btn(document.fullscreenElement?'Exit full screen':'Full screen','showroom-fullscreen'))}${shelfControls()}<div id="showroom-featured">${showroomFeatured()}</div><div class="showroom-collection-head"><h2>The collection <span id="showroom-count" class="muted">${current()._view?.list?.total??showroomCars().length} cars</span></h2><div class="showroom-controls"><label class="search">${icon('search')}<input id="showroom-search" value="${esc(showroom.query)}" placeholder="Search the showroom…" aria-label="Search showroom"></label>${local()?`<div class="segment"><button class="btn ${!showroom.favourites?'on':''}" data-action="showroom-filter" data-id="all" aria-pressed="${!showroom.favourites}">All cars</button><button class="btn ${showroom.favourites?'on':''}" data-action="showroom-filter" data-id="favourites" aria-pressed="${showroom.favourites}">Favourites</button></div>`:''}<select id="showroom-usage" aria-label="Filter showroom by usage"><option value="">All uses</option>${usages.map(u=>`<option ${showroom.usage===u?'selected':''}>${esc(u)}</option>`).join('')}</select><select id="showroom-sort" ${showroom.shelf?'disabled':''} aria-label="Sort showroom">${[['name','Name A–Z'],['maker','Manufacturer'],['updated','Recently changed']].map(([value,label])=>`<option value="${value}" ${showroom.sort===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div id="showroom-gallery">${showroomGallery()}${viewPager(current()._view?.list)}</div></div>`;}
function refreshShowroom(){if(page!=='Showroom')return;if(local()&&current()._view)return loadView();$('#showroom-featured').innerHTML=showroomFeatured();$('#showroom-gallery').innerHTML=showroomGallery();applyPhotoFocus();$('#showroom-count').textContent=showroomCars().length+' cars';for(const el of document.querySelectorAll('[data-action="showroom-filter"]')){const on=(el.dataset.id==='favourites')===showroom.favourites;el.classList.toggle('on',on);el.setAttribute('aria-pressed',String(on));}}
function pauseShowroom(){clearTimeout(showroom.timer);showroom.timer=null;if(showroom.viewer)showroom.viewer.playing=false;}
function closeShowroom(){pauseShowroom();showroom.fullscreenGeneration=(showroom.fullscreenGeneration||0)+1;const id=showroom.viewer?.id;showroom.viewer=null;const dialog=$('#showroom-viewer');if(dialog.open)dialog.close();if(showroom.fullscreen&&document.fullscreenElement)document.exitFullscreen().catch(()=>{});if(page==='Showroom'&&id)document.querySelector(`[data-action="showroom-open"][data-id="${CSS.escape(id)}"]`)?.focus({preventScroll:true});}
function prepareShowroom(){showroomContext();if(local()&&showroom.shelf&&!db.planning.shelves.some(s=>s.id===showroom.shelf))showroom.shelf='';if(page!=='Showroom')closeShowroom();else{if(showroom.viewer){const c=showroomCar(showroom.viewer.id);if(!c||c.archived)closeShowroom();else renderShowroomViewer();}scheduleCover();}}
function renderShowroomViewer(){const state=showroom.viewer,c=state&&showroomCar(state.id);if(!c){closeShowroom();return;}const photos=ShowroomModel.photos(c),list=showroomSequence();state.photo=Math.min(state.photo,Math.max(0,photos.length-1));const photo=photos[state.photo],dialog=$('#showroom-viewer'),focus=document.activeElement?.closest('#showroom-viewer [data-action]')?.dataset.action;dialog.innerHTML=`<div class="showroom-viewer-head"><div><h2 id="showroom-viewer-title">${esc(c.name)}</h2><p class="muted">${esc([c.maker,c.scale].filter(Boolean).join(' · '))} · Car ${list.findIndex(x=>x.id===c.id)+1} of ${list.length}</p></div><button class="btn" data-action="showroom-close" aria-label="Close photo viewer">✕ Close</button></div><div class="showroom-viewer-stage ${state.layout==='history'?'with-story':''}">${state.layout==='history'?showroomStory(c):''}<div class="showroom-viewer-image">${photo?`<img src="${esc(photo.data)}" data-focus-car="${esc(c.id)}" data-focus-photo="${esc(photoKey(c,photo))}" alt="${esc(c.name+' · '+photo.name)}">`:`<div class="showroom-placeholder">${icon('car')}<span>No photograph yet</span><p>Add photographs from this car’s Photos & documents section.</p></div>`}</div></div><div class="showroom-viewer-footer"><div class="actions">${btn('← Previous car','showroom-prev')}${btn('Next car →','showroom-next')}</div><div class="actions">${photos.length>1?btn('‹ Photo','showroom-photo-prev')+`<span class="tiny muted">Photo ${state.photo+1} / ${photos.length}</span>`+btn('Photo ›','showroom-photo-next'):''}</div><div class="actions">${local()?btn('Frame photo','viewer-photo-focus','',c.id):''}${btn(state.playing?'Pause':'Play','showroom-toggle-play')}${btn(document.fullscreenElement?'Exit full screen':'Full screen','showroom-fullscreen')}${btn('View car →','showroom-car','primary',c.id)}</div></div><p class="showroom-viewer-hint muted">Arrow keys: previous / next car · P: pause / play · Escape: close${state.playing?' · Advances every ${state.seconds||showroom.preferences.presentation.seconds} seconds':''}</p>`;dialog.classList.toggle('presentation',!!state.presentation);dialog.classList.toggle('with-history',state.layout==='history');applyPhotoFocus();for(const action of ['showroom-prev','showroom-next'])dialog.querySelector(`[data-action="${action}"]`).disabled=list.length<2;if(focus)dialog.querySelector(`[data-action="${focus}"]`)?.focus({preventScroll:true});}
function scheduleShowroom(){clearTimeout(showroom.timer);showroom.timer=null;if(!showroom.viewer?.playing||document.hidden||showroomSequence().length<2)return;showroom.timer=setTimeout(async()=>{if(!showroom.viewer||page!=='Showroom'||showroom.context!==showroomKey()){closeShowroom();return;}try{if(!$('#dialog').open&&!showroom.moving)await moveShowroom(1);scheduleShowroom();}catch(e){pauseShowroom();toast(e.message,true);}},(showroom.viewer.seconds||showroom.preferences.presentation.seconds)*1000);}
async function moveShowroom(direction){if(!showroom.viewer||showroom.moving)return;const list=showroomSequence();if(!list.length){closeShowroom();return;}showroom.moving=true;try{const index=list.findIndex(c=>c.id===showroom.viewer.id);showroom.viewer.id=list[(index+direction+list.length)%list.length].id;showroom.viewer.photo=0;if(local()&&current()._view)await loadView();else renderShowroomViewer();}finally{showroom.moving=false;}}
async function openShowroom(id,playing=false,options={}){let list=local()&&current()._view?.showroomChoices||showroomCars();if(options.ids){const byId=new Map(showroomAllChoices().map(c=>[c.id,c]));list=options.ids.map(id=>byId.get(id)).filter(Boolean);}else if(id&&!list.some(c=>c.id===id))list=showroomAllChoices();if(!list.length){toast('No cars match this showroom selection.');return;}pauseShowroom();const opened=showroom.viewer={...options,ids:list.map(c=>c.id),id:list.find(c=>c.id===id)?.id||list[0].id,photo:0,playing};if(local()&&current()._view)await loadView();else renderShowroomViewer();if(showroom.viewer!==opened||page!=='Showroom')return;const dialog=$('#showroom-viewer');if(!dialog.open)dialog.showModal();dialog.querySelector('[data-action="showroom-close"]').focus();scheduleShowroom();return opened;}
async function fullscreenShowroom(){if(document.fullscreenElement){showroom.keepViewerOnExit=true;try{await document.exitFullscreen();}catch(error){showroom.keepViewerOnExit=false;throw error;}return;}const generation=showroom.fullscreenGeneration=(showroom.fullscreenGeneration||0)+1;showroom.keepViewerOnExit=false;showroom.fullscreen=true;try{await document.documentElement.requestFullscreen();if(generation!==showroom.fullscreenGeneration&&document.fullscreenElement)await document.exitFullscreen();}catch(error){showroom.fullscreen=false;throw Error('Full screen is unavailable: '+error.message);}}
async function showroomAction(action,id){if(['showroom-photo-next','showroom-photo-prev','showroom-toggle-play'].includes(action)&&!showroom.viewer)return true;switch(action){
  case 'showroom-open':await openShowroom(id);return true;
  case 'showroom-cover-options':showroomOptions('cover');return true;
  case 'showroom-presentation':case 'showroom-play':showroomOptions('presentation');return true;
  case 'showroom-cover-pause':showroom.coverPaused=!showroom.coverPaused;clearTimeout(showroom.coverTimer);showroom.coverTimer=null;await refreshShowroom();scheduleCover();return true;
  case 'showroom-history':{const c=showroomCar(id);if(!c)return true;pauseShowroom();modal('Real Racing History · '+c.name,showroomStory(c,true)+btn('Open car history →','showroom-history-car','',id),null);return true;}
  case 'showroom-history-car':$('#dialog').close();closeShowroom();page='Cars';carId=id;section='Real Car History';render();return true;
  case 'showroom-close':closeShowroom();return true;
  case 'showroom-car':closeShowroom();page='Cars';carId=id;section='Overview';render();return true;
  case 'showroom-fullscreen':await fullscreenShowroom();return true;
  case 'showroom-next':case 'showroom-prev':await moveShowroom(action==='showroom-next'?1:-1);scheduleShowroom();return true;
  case 'showroom-photo-next':case 'showroom-photo-prev':{const c=showroomCar(showroom.viewer.id),count=ShowroomModel.photos(c).length;if(count)showroom.viewer.photo=(showroom.viewer.photo+(action==='showroom-photo-next'?1:-1)+count)%count;renderShowroomViewer();scheduleShowroom();return true;}
  case 'showroom-toggle-play':if(showroom.viewer.playing)pauseShowroom();else{showroom.viewer.playing=true;scheduleShowroom();}renderShowroomViewer();return true;
  case 'showroom-filter':showroom.favourites=id==='favourites';await refreshShowroom();return true;
  case 'showroom-clear':showroom.shelf='';showroom.query='';showroom.usage='';showroom.favourites=false;render();return true;
  case 'showroom-favourite':{const c=db.cars.find(c=>c.id===id);await change('car.favourite',{id,revision:c.revision,value:!c.favourite});await refreshShowroom();document.querySelector(`[data-action="showroom-favourite"][data-id="${CSS.escape(id)}"]`)?.focus({preventScroll:true});return true;}
}return false;}
document.addEventListener('input',event=>{if(event.target.id==='showroom-search'){showroom.query=event.target.value;if(local()&&current()._view)scheduleView();else refreshShowroom();}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='showroom-usage'){showroom.usage=el.value;await refreshShowroom();}if(el.id==='showroom-sort'){showroom.sort=el.value;await refreshShowroom();}}catch(error){if(!finishClubQueued(error)){toast(error.message,true);refreshShowroom();}}});
document.addEventListener('keydown',event=>{if(!$('#showroom-viewer').open||$('#dialog').open||event.altKey||event.ctrlKey||event.metaKey)return;const action={'ArrowLeft':'showroom-prev','ArrowRight':'showroom-next','Escape':'showroom-close'}[event.key];if(action){event.preventDefault();showroomAction(action).catch(e=>toast(e.message,true));}else if(!event.repeat&&(event.key.toLowerCase()==='p'||event.code==='Space'&&event.target.tagName!=='BUTTON')){event.preventDefault();showroomAction('showroom-toggle-play').catch(e=>toast(e.message,true));}});
document.getElementById('showroom-viewer').addEventListener('cancel',event=>{event.preventDefault();closeShowroom();});
document.getElementById('showroom-viewer').addEventListener('close',event=>{if(!event.target.open&&showroom.viewer)closeShowroom();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(showroom.coverTimer);showroom.coverTimer=null;if(showroom.viewer){pauseShowroom();renderShowroomViewer();}}else if(showroom.preferences)scheduleCover();});
document.addEventListener('fullscreenchange',()=>{const closeViewer=!document.fullscreenElement&&showroom.fullscreen&&showroom.viewer&&!showroom.keepViewerOnExit;document.documentElement.toggleAttribute('data-showroom-fullscreen',!!document.fullscreenElement&&showroom.fullscreen);if(!document.fullscreenElement){showroom.fullscreen=false;showroom.keepViewerOnExit=false;pauseShowroom();if(closeViewer)closeShowroom();}if(showroom.viewer)renderShowroomViewer();for(const el of document.querySelectorAll('[data-action="showroom-fullscreen"]'))el.textContent=document.fullscreenElement?'Exit full screen':'Full screen';});
